from __future__ import annotations

import hashlib
from pathlib import Path

from flask import Flask, Response, abort, jsonify, request


def create_app(data_dir: Path) -> Flask:
    app = Flask(__name__)
    app.config["DATA_DIR"] = data_dir

    @app.get("/healthz")
    def healthz():
        return "", 200

    @app.put("/blobs/<path:key>")
    def put_blob(key: str):
        content = request.get_data()

        blob_path = data_dir / key
        blob_path.parent.mkdir(parents=True, exist_ok=True)
        blob_path.write_bytes(content)

        return (
            jsonify(
                key=key,
                sha256=hashlib.sha256(content).hexdigest(),
                size=len(content),
            ),
            201,
        )

    @app.get("/blobs/<path:key>")
    def get_blob(key: str):
        blob_path = data_dir / key
        if not blob_path.is_file():
            abort(404)
        return Response(blob_path.read_bytes(), mimetype="application/octet-stream")

    return app

